import{z as i,x as A,o as e,c as s,q as o,j as B,D as E,d as l,s as n,S as r}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"批大小的经济学","description":"","frontmatter":{"title":"批大小的经济学","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ce-batch-economics.md","filePath":"llm/ce-batch-economics.md","lastUpdated":1791413859000}'),c={name:"llm/ce-batch-economics.md"};function d(p,a,h,m,T,D){const t=A("Mermaid");return e(),s("div",null,[a[2]||(a[2]=o('<h1 id="批大小的经济学" tabindex="-1">批大小的经济学 <a class="header-anchor" href="#批大小的经济学" aria-label="Permalink to &quot;批大小的经济学&quot;">​</a></h1><div class="epigraph"><p>批不改变模型，只改变你为空闲带宽付多少钱；它是推理经济学里最大的单一旋钮，也是最先撞上延迟墙的一个。</p><footer>—— 据 Pope et al., 2022 与本仓库连续批处理课的吞吐口径整理</footer></div><p><a href="/llm/ce-per-million-benchmarks">上一课</a>把单价钉成画像加权的自测基准，其中并发口径一钉留了悬念：为什么同一个模型，批从 1 到饱和，单价能差一个数量级。本课写批的边际账——批怎么把钱省出来、在哪停下，以及没打满怎么记账。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自建集群的时租是固定的，产出的 token 却随批变：批越大，同样的租时产出越多，单价越低。但批不是免费午餐——批越大，每请求的排队与生成延迟越高，KV 显存占用线性上涨，SLO 顶住后批就不能再加。缺口是一个边际账：批的工作点在哪、离 SLO 上限还有多少、没打满的租时算谁的。不记账的两种错：一是按批 1 的延迟印象运营，集群常年半空转，单价虚高一倍还以为「模型贵」；二是照抄别人家的最大批，自己的 SLO 一压就雪崩。</p><h3 id="单价函数" tabindex="-1">单价函数 <a class="header-anchor" href="#单价函数" aria-label="Permalink to &quot;单价函数&quot;">​</a></h3><p>时段成本固定为 \\(F\\)，批 \\(B\\) 下的有效吞吐为 \\(T(B)\\)，则单位 token 成本</p> \\[c(B) = \\frac{F}{T(B)},\\qquad T(B) \\approx \\min(\\alpha B,\\ T_{\\max}) \\]<p>decode 段每步要把全部权重与 KV 从显存搬一遍，算术强度随批近似线性上升，直到带宽打满；<a href="/llm/sch-continuous-batching-deep">连续批处理课</a>的 token 间并行给了 \\(T(B)\\) 的形状，MoE 的批行为另有专家路由的修正，见 <a href="/llm/moe-inference-batching">MoE 推理批处理</a>。打满率 \\(u\\) 把它与采购口径接上：单价 $= $ 时租价 \\(\\div\\ (u \\cdot T_{\\max})\\)——上一课利用率口径的那笔账，在这里兑现成批的工作点。</p>',9)),(e(),B(r,null,{default:E(()=>[n(t,{id:"mermaid-23",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22%E6%89%B9%E5%A4%A7%E5%B0%8F%20B%22%5D%20--%3E%20T%5B%22%E6%9C%89%E6%95%88%E5%90%9E%E5%90%90%20T(B)%22%5D%0A%20%20B%20--%3E%20L%5B%22%E5%BB%B6%E8%BF%9F%EF%BC%9ATTFT%20%E4%B8%8E%20TPOT%22%5D%0A%20%20B%20--%3E%20M%5B%22KV%20%E6%98%BE%E5%AD%98%E5%8D%A0%E7%94%A8%22%5D%0A%20%20T%20--%3E%20C%5B%22%E5%8D%95%E4%BD%8D%E6%88%90%E6%9C%AC%20c(B)%22%5D%0A%20%20L%20--%3E%20SLO%7B%22SLO%20%E7%BA%A6%E6%9D%9F%22%7D%0A%20%20M%20--%3E%20CAP%7B%22%E5%AE%B9%E9%87%8F%E7%BA%A6%E6%9D%9F%22%7D%0A%20%20SLO%20--%3E%20WP%5B%22%E5%B7%A5%E4%BD%9C%E7%82%B9%EF%BC%9ASLO%20%E5%86%85%E7%9A%84%E6%9C%80%E5%A4%A7%E6%89%B9%22%5D%0A%20%20CAP%20--%3E%20WP%0A%20%20C%20--%3E%20WP%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<p><span class="marginnote">术语翻译：成本批次（cost batch）= 把「推理一次值多少钱」拆成 token 费、请求费与固定吞吐摊销的记账单位；它与 token batch 的区别是后者只数长度，前者还数「这一次调用替人省了多少工」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>找工作点的流程：先钉 SLO（TPOT 与 TTFT 的分档沿用服务调度的指标口径），再从低批起步、按固定步长加压，同时记录吞吐、TPOT、TTFT、KV 水位四条线，停在第一条越线之前。离线与在线分池：能容忍小时级延迟的流量走批量接口或夜间池，把在线池的批空间让出来；两池的账分开记，混在一池里,离线流量会把在线的尾延迟顶穿。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>批为什么先赚后亏：decode 每步搬运的权重量与批无关，步时延几乎不变，而每步产出的 token 数随批成倍——带宽账被摊薄，这是「赚」的全部来源；过了容量点，KV 装不下就得抢占与重算（<a href="/llm/sch-preemption-migration">抢占与请求迁移</a>的机制），重算的 token 白付一遍，单价不降反升。延迟是硬边界：SLO 给了批的上限，工作点是「SLO 内的最大批」而不是「吞吐峰值批」——后者往往就在违约线上。没打满的账要显式记为空转成本：时租照付、token 没产出，这份损失属于容量规划（弹性伸缩能不能救），不属于模型选型——把空转归罪于模型，是采购会上最常见的张冠李戴。</p>',5)),(e(),B(r,null,{default:E(()=>[n(t,{id:"mermaid-39",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E6%89%B9%E5%86%8D%E5%8A%A0%E4%B8%80%EF%BC%8C%E5%A4%9A%E5%87%BA%E7%9A%84%20token%20%E8%8A%B1%E5%A4%9A%E5%B0%91%E9%92%B1%EF%BC%9F%22%7D%20--%3E%20A%5B%22%E5%B8%A6%E5%AE%BD%E6%9C%AA%E9%A5%B1%E5%92%8C%E5%8C%BA%EF%BC%9AKV%20%E8%BF%98%E8%A3%85%E5%BE%97%E4%B8%8B%22%5D%0A%20%20A%20--%3E%20A2%5B%22%E6%9D%83%E9%87%8D%E6%90%AC%E8%BF%90%E4%B8%8D%E5%8F%98%E3%80%81%E4%BA%A7%E5%87%BA%E6%88%90%E5%80%8D%EF%BC%8C%E5%8D%95%E4%BB%B7%E8%A2%AB%E6%91%8A%E8%96%84%22%5D%0A%20%20Q%20--%3E%20B%5B%22%E8%B6%8A%E8%BF%87%E5%AE%B9%E9%87%8F%20%2F%20SLO%20%E7%82%B9%22%5D%0A%20%20B%20--%3E%20B2%5B%22KV%20%E8%A3%85%E4%B8%8D%E4%B8%8B%EF%BC%9A%E6%8A%A2%E5%8D%A0%E3%80%81%E6%8D%A2%E5%87%BA%E3%80%81%E9%87%8D%E7%AE%97%22%5D%0A%20%20B2%20--%3E%20B3%5B%22%E9%87%8D%E7%AE%97%E7%9A%84%20token%20%E7%99%BD%E4%BB%98%E4%B8%80%E9%81%8D%EF%BC%8C%E6%8E%92%E9%98%9F%E5%8F%98%E9%95%BF%EF%BC%8C%E5%8D%95%E4%BB%B7%E5%9B%9E%E5%8D%87%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<p><span class="marginnote">代入数字：假设一张卡时租 2 美元，批 1 时每小时只产出 5 万 token，单价就是 4 美分/千 token；批打满后每小时产出 50 万 token，时租一分没涨，单价立刻降到 0.4 美分。十倍的差价没有动模型一个参数，全部来自「同一小时的租金摊给了十倍的 token」。</span></p><p><span class="marginnote">同卡同模型，批 1 的 decode 吞吐约是带宽饱和批的十分之一到几分之一（取决于权重搬运与 KV 占用之比）；批量接口之所以能给五折上下的折扣，正是因为它把批打满、把延迟换成时延容忍。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>\\(c(B)\\) 的形状随硬件代际漂移：新一代卡算力涨得比带宽快，带宽饱和来得更早，批的边际收益区间变窄——上代硬件的批经验不能平移。批的收益在 MoE 上要打折扣：专家路由让有效批按专家数摊薄。最后，批经济学不覆盖 prefill 主导的流量：输入重的画像（上一课的检索型）里，批的杠杆让位给前缀共享——那是下一课的账。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>单价函数 \\(c(B)=F/T(B)\\)：decode 带宽饱和前，批把权重搬运摊薄，这是批省钱的全部分析。</li><li>工作点钉在「SLO 内的最大批」，不是吞吐峰值批；容量点后抢占与重算让单价回升。</li><li>没打满要记为空转成本，归容量规划管，不归模型选型管。</li><li>离线与在线分池，批量折扣是把延迟换成单价的产品形态。</li><li>出处：Pope et al., 2022；吞吐形状与工作点口径见本仓库连续批处理课，MoE 修正见 MoE 推理批处理课。</li></ul>',6))])}const u=i(c,[["render",d]]);export{C as __pageData,u as default};
